// Builds and runs the same CREATE/DETACH DELETE statements api/'s routes
// used to run with real Bolt parameters — now built as literal Cypher text
// via cypherLiteral/cypherPropsLiteral, since the neo4j-datasource query
// target has no parameters field of its own. See cypherClient.ts for the
// escaping this relies on for injection safety.
import { assertValidIdentifier, cypherPropsLiteral, cypherLiteral, runCypher } from './cypherClient';
export async function createNode(datasourceName, labels, properties) {
    labels.forEach((label) => assertValidIdentifier(label, 'label'));
    await runCypher(datasourceName, `CREATE (n:${labels.join(':')}) SET n = ${cypherPropsLiteral(properties)} RETURN n`);
}
export async function createRelationship(datasourceName, sourceId, targetId, type, properties) {
    assertValidIdentifier(type, 'relationship type');
    await runCypher(datasourceName, `MATCH (a), (b) WHERE elementId(a) = ${cypherLiteral(sourceId)} AND elementId(b) = ${cypherLiteral(targetId)} ` +
        `CREATE (a)-[r:${type}]->(b) SET r = ${cypherPropsLiteral(properties)} RETURN r`);
}
export async function updateNodeLabels(datasourceName, id, labelsToAdd, labelsToRemove) {
    labelsToAdd.forEach((label) => assertValidIdentifier(label, 'label'));
    labelsToRemove.forEach((label) => assertValidIdentifier(label, 'label'));
    const clauses = [];
    if (labelsToAdd.length > 0)
        clauses.push(`SET n:${labelsToAdd.join(':')}`);
    if (labelsToRemove.length > 0)
        clauses.push(`REMOVE n:${labelsToRemove.join(':')}`);
    if (clauses.length === 0)
        return;
    await runCypher(datasourceName, `MATCH (n) WHERE elementId(n) = ${cypherLiteral(id)} ${clauses.join(' ')} RETURN n`);
}
export async function updateRelationshipProperties(datasourceName, id, properties) {
    await runCypher(datasourceName, `MATCH ()-[r]->() WHERE elementId(r) = ${cypherLiteral(id)} SET r += ${cypherPropsLiteral(properties)} RETURN r`);
}
export async function updateNodeProperties(datasourceName, id, properties) {
    await runCypher(datasourceName, `MATCH (n) WHERE elementId(n) = ${cypherLiteral(id)} SET n += ${cypherPropsLiteral(properties)} RETURN n`);
}
export async function deleteNode(datasourceName, label, id) {
    assertValidIdentifier(label, 'label');
    await runCypher(datasourceName, `MATCH (n:${label}) WHERE elementId(n) = ${cypherLiteral(id)} DETACH DELETE n RETURN count(n) AS deleted`);
}
export async function deleteRelationship(datasourceName, id) {
    await runCypher(datasourceName, `MATCH ()-[r]->() WHERE elementId(r) = ${cypherLiteral(id)} DELETE r RETURN count(r) AS deleted`);
}
